const CSS = `
.rr{--bg:#f4f6fb;--card:#ffffff;--ink:#182235;--muted:#61708a;--line:#e3e8f2;--brand:#3355d6;--blue:#3355d6;--amber:#d4a53a;--green:#20865c;--soft-blue:#eef2ff;--soft-amber:#fff8e1;--soft-green:#eaf5f0;--mono:"Courier New",Courier,monospace;font-family:"Iowan Old Style","Palatino Linotype","Bookman Old Style",Georgia,serif;color:var(--ink);background:var(--bg);min-height:100dvh;padding:20px 20px 56px;box-sizing:border-box}
.rr *,.rr *::before,.rr *::after{box-sizing:border-box}
.rr-wrap{max-width:1120px;margin:0 auto}
.rr-top{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;margin-bottom:18px}
.docbar{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;padding:12px 16px;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0 0;box-shadow:0 4px 16px #0000001a}
.docbar-left{display:flex;flex-direction:column;gap:2px;min-width:0}
.docbar-left h1{margin:0;font-size:20px;font-family:var(--mono);letter-spacing:.02em}
.docbar-right{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:flex-end}
.docwrap{display:grid;grid-template-columns:minmax(230px,0) 1fr;gap:16px;align-items:start;margin-top:12px}
.docsidebar{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 12px;align-self:start}
.docsidebar-title{margin:0 0 12px 10px;font-size:12px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--ink)}
.docsidebar-list{display:flex;flex-direction:column;gap:6px}
.docfile{display:flex;gap:12px;align-items:center;width:100%;text-align:left;padding:11px 12px;background:transparent;border:1px solid transparent;border-radius:10px;cursor:pointer;font-family:var(--mono);font-size:13px;transition:.15s}
.docfile:hover{background:var(--soft-blue)}
.docfile.on{border-color:var(--brand);background:var(--soft-amber);box-shadow:0 0 0 1px var(--line)}
.docfile-icon{font-size:18px;line-height:1;flex:0 0 18px}
.docfile-body{display:flex;flex-direction:column;gap:2px;min-width:0}
.docfile-name{display:block;color:var(--ink);font-weight:800;line-height:1.3;font-size:13px}
.docfile-meta{display:block;font-size:11px;color:var(--muted);line-height:1.3;letter-spacing:.04em}
.docfile.on .docfile-name{color:var(--brand)}
.docmain{min-width:0}
.round-step{margin:18px 0 22px}
.round-step-title{margin:0 0 12px;font-size:13px;font-weight:800;font-family:var(--mono);letter-spacing:.15em;text-transform:uppercase;color:var(--brand)}
.roundbar{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;align-items:stretch}

.rr-kicker{font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--brand);font-family:var(--mono)}
.rr h1{font-size:clamp(23px,3.4vw,34px);margin:6px 0 6px;line-height:1.25}
.rr-sub{margin:0;color:var(--muted);font-size:14px}
.langbar{display:flex;gap:4px;background:var(--card);border:1px solid var(--line);border-radius:999px;padding:4px;box-shadow:0 2px 14px #00000020}
.langbar button{border:0;background:transparent;border-radius:999px;padding:7px 14px;font-size:13px;font-weight:800;color:var(--muted);cursor:pointer}
.langbar button.on{background:var(--brand);color:#fff;box-shadow:0 0 0 2px var(--line)}
.roundtab{min-width:0;height:100%;text-align:left;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:15px 17px;cursor:pointer;transition:.18s;box-shadow:0 2px 10px #00000018;display:flex;flex-direction:column}
.roundtab:hover{transform:translateY(-2px);border-color:#2b3c5c}
.roundtab.on{border-color:var(--brand);background:var(--soft-amber);box-shadow:0 0 0 1px var(--brand);}
.roundtab-top{display:flex;align-items:center;gap:10px;font-weight:800}
.roundnum{width:28px;height:28px;border-radius:9px;background:#eef2ff;color:var(--brand);display:grid;place-items:center;font-size:13px;font-family:var(--mono)}
.roundtab.on .roundnum{background:var(--brand);color:#fff}
.pill{margin-left:auto;font-size:10px;font-weight:800;padding:4px 8px;border-radius:99px;background:#eef2ff;color:var(--muted);border:1px solid var(--line)}
.pill.off{background:#f0f2f6;color:var(--muted);border-color:var(--line)}
.roundtab small{display:block;margin-top:7px;color:var(--muted);font-size:12px;line-height:1.5;flex:1}
.roundtab.locked{opacity:.62;cursor:not-allowed;background:transparent}
.roundtab.locked:hover{transform:none}
.roundtab.locked .roundnum{background:#eceff5;color:#9aa4b6}
.roundtab:disabled{box-shadow:none}
.pill.done{background:var(--soft-amber);color:var(--brand);border-color:var(--brand)}
.pill.lock{background:#eceff4;color:#8a94a6}
.progress{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 16px;margin:0 0 16px}
.progress-meta{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12px;font-weight:800;color:var(--muted);margin-bottom:8px}
.progress-meta .ok{color:#2a9a67}
.track{height:7px;border-radius:99px;background:#e9edf5;overflow:hidden}
.fill{height:100%;border-radius:99px;background:linear-gradient(90deg,var(--brand),#7e98f1);transition:width .3s}
.cardhead{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.readmark{font-size:10px;font-weight:800;color:#1d7a45;background:#e8f7ee;border-radius:6px;padding:4px 8px}
.rounddone{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-top:18px;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px 18px;font-size:13px;color:var(--muted)}
.rounddone.ready{border-color:var(--brand);background:var(--soft-amber);color:var(--ink)}
.nextbtn{border:0;border-radius:10px;padding:11px 18px;font-weight:800;font-size:13px;color:#fff;background:var(--brand);cursor:pointer;white-space:nowrap}
.nextbtn:disabled{background:#b9c1cf;cursor:not-allowed}
.notice.ok{border-style:solid;border-color:#bfe6cf;background:#f2fbf6;color:#1d7a45}
.sectionhead{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:0 0 14px}
.sectionhead h2{font-size:18px;margin:0}
.sectionhead span{font-size:12px;color:var(--muted)}
.openrow{margin:18px 0 2px;text-align:center}
.openbtn{border:3px solid var(--brand);border-radius:14px;padding:11px 26px;font-weight:800;font-size:14px;color:var(--brand);background:transparent;font-family:var(--mono);letter-spacing:.08em;cursor:pointer;transition:.15s}
.openbtn:hover:not(:disabled){background:var(--soft-amber);box-shadow:0 0 0 3px var(--line)}
.openbtn:disabled{color:var(--muted);border-color:#3b3b44;cursor:not-allowed}
.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;align-items:stretch}
.card{background:var(--card);border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:0 3px 14px #00000018;transition:.18s;display:flex;flex-direction:column;height:100%}
.card.sel{border-color:var(--accent);box-shadow:0 10px 26px #00000026;background:var(--soft-amber)}
.card-main{width:100%;flex:1;text-align:left;border:0;background:linear-gradient(180deg,var(--soft) 0,var(--card) 120px);padding:20px;cursor:pointer;display:flex;flex-direction:column;color:inherit}
.card-main:hover{background:linear-gradient(180deg,var(--soft) 0,var(--card) 150px)}
.strip{height:6px;background:var(--accent)}
.rolebadge{width:46px;height:46px;flex:0 0 46px;display:grid;place-items:center;border-radius:14px;background:var(--accent);color:var(--bg);font-size:24px;font-weight:900;line-height:1;box-shadow:0 5px 14px #00000030}
.chip{display:inline-block;font-size:11px;font-weight:800;letter-spacing:.08em;color:var(--accent);background:var(--card);border:1px solid color-mix(in srgb,var(--accent) 40%,var(--line));padding:6px 10px;border-radius:7px;text-transform:uppercase}
.card h3{font-size:22px;margin:12px 0 3px;color:var(--ink);font-family:var(--mono)}
.play{margin:0;font-size:13px;font-weight:600;color:var(--muted);line-height:1.5}
.arrow{margin-top:auto;display:flex;align-items:center;justify-content:center;gap:8px;border-radius:11px;background:var(--accent);color:#fff;font-size:14px;font-weight:800;padding:12px 14px;box-shadow:0 5px 14px #00000026;transition:.18s}
.card:hover .arrow{transform:translateY(-1px);box-shadow:0 8px 18px #00000033}
.arrow.on{background:var(--card);color:var(--accent);border:2px solid var(--accent);box-shadow:0 0 0 2px var(--soft-amber)}
.linkbtn{border:0;background:transparent;color:var(--brand);font-weight:700;font-size:13px;cursor:pointer;padding:6px 0;text-decoration:underline;text-underline-offset:3px}
.notice{background:var(--card);border:1px dashed var(--line);border-radius:14px;padding:18px;color:var(--muted);font-size:13px;line-height:1.7;margin-top:14px}
.cf-overlay{position:fixed;inset:0;background:#0d1729b8;display:flex;align-items:center;justify-content:center;padding:18px;z-index:60;backdrop-filter:blur(2px)}
.cf-dialog{background:var(--card);border:1px solid var(--line);border-radius:16px;width:min(480px,100%);padding:24px;box-shadow:0 24px 60px #00000040}
.cf-head{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.cf-stamp{font-family:var(--mono);font-size:11px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:var(--brand);border:2px solid var(--brand);border-radius:6px;padding:4px 10px;transform:rotate(-4deg)}
.cf-head h2{margin:0;font-size:20px;font-family:var(--mono)}
.cf-text{margin:16px 0 0;font-size:14px;line-height:1.7;color:var(--ink)}
.cf-actions{display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap;margin-top:22px}
.cf-cancel{border:1px solid var(--line);background:var(--card);color:var(--muted);border-radius:10px;padding:10px 18px;font-weight:800;font-size:13px;cursor:pointer}
.cf-confirm{border:0;background:var(--brand);color:#fff;border-radius:10px;padding:10px 18px;font-weight:800;font-size:13px;cursor:pointer}
.overlay{position:fixed;inset:0;background:#0d1729e6;display:flex;align-items:center;justify-content:center;padding:18px;z-index:50;backdrop-filter:blur(3px)}
.modal{position:relative;background:var(--card);background-image:radial-gradient(ellipse 120% 220% at 50% 0%,rgba(212,165,58,.06),transparent 55%),radial-gradient(ellipse 120% 220% at 50% 100%,rgba(90,140,241,.05),transparent 55%);border:1px solid var(--line);border-radius:18px;width:min(940px,94vw);max-height:92vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 28px 70px #0000002e}
.docstamp{position:absolute;top:26px;right:26px;transform:rotate(14deg);font-family:var(--mono);font-size:34px;font-weight:900;letter-spacing:2px;text-transform:uppercase;color:var(--brand);opacity:.55;pointer-events:none;white-space:nowrap;border:3px solid var(--brand);border-radius:8px;padding:5px 14px}
.mhead{padding:22px 28px 18px;border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:14px;align-items:stretch;flex-shrink:0}
.mhead-tools{display:flex;align-items:center;gap:8px;justify-content:space-between;width:100%;flex-shrink:0}
.mhead-title{min-width:0;align-self:flex-start}
.mhead h2{margin:8px 0 0;font-size:26px;font-family:var(--mono);font-weight:800;letter-spacing:.03em;color:var(--ink)}
.mhead p{margin:6px 0 0;font-size:13px;color:var(--muted)}
.docmeta{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;padding-top:14px;border-top:1px solid var(--line);font-family:var(--mono);font-size:11px;color:var(--muted);letter-spacing:.05em;font-weight:700}
.mhead-tools .langbar{background:var(--bg);border-color:var(--line);box-shadow:none;padding:3px}
.mhead-tools .langbar button{padding:5px 11px;font-size:12px}
.xbtn{border:1px solid var(--line);background:var(--card);width:34px;height:34px;border-radius:10px;font-size:19px;cursor:pointer;color:var(--muted)}
.tabs{display:flex;gap:4px;padding:10px 20px 0;border-bottom:1px solid var(--line);overflow-x:auto;flex-shrink:0}
.tabs button{border:0;background:transparent;padding:10px 13px;font-size:13px;font-weight:700;color:var(--muted);cursor:pointer;border-bottom:3px solid transparent;white-space:nowrap}
.tabs button.on{color:var(--brand);border-bottom-color:var(--brand)}
.tabs .lock{color:#a06b12}
.mbody{position:relative;padding:26px 28px 30px;overflow-y:auto;line-height:1.75;font-size:14px;flex:1 1 auto;min-height:0}
.mbody::after{content:"";position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--brand) 30%,var(--brand) 70%,transparent);opacity:.5}
.mbody h4{margin:0 0 10px;font-size:15px}
.mbody p{margin:0 0 12px}
.mbody ul{margin:8px 0 14px;padding-left:20px}
.mbody li{margin:5px 0}
.sec{margin-bottom:22px;padding-bottom:18px;border-bottom:1px solid var(--line)}
.sec:last-child{border-bottom:0}
.sec.firm{background:#fff6f2;border-left:4px solid #e0723f;border-radius:8px;padding:12px 14px}
.sec.firm h4{color:var(--brand)}
.tablewrap{overflow-x:auto;margin:12px 0 18px}
table{border-collapse:collapse;width:100%;font-size:13px}
th,td{border:1px solid var(--line);padding:9px 11px;text-align:left;vertical-align:top;line-height:1.6}
th{background:#eef2ff;color:var(--brand);font-size:12px}
.secretbox{background:var(--soft-amber);border:1px solid var(--brand);border-radius:14px;padding:20px}
.doc-h{font-weight:800;color:var(--ink);line-height:1.4;margin:20px 0 8px}
.doc-h.lvl1{font-size:16px;padding:8px 0;border-bottom:2px solid var(--brand)}
.doc-h.lvl2{font-size:14px;padding-left:10px;border-left:4px solid var(--brand)}
.doc-p{margin:0 0 12px}
.doc-note{margin:0 0 12px;font-size:13px;color:var(--muted);font-style:italic}
.doc-meta{margin:6px 0;text-align:center;font-size:10px;color:var(--muted);letter-spacing:.02em;font-family:var(--mono)}
.doc-table-wrap{overflow-x:auto;margin:10px 0 18px}
.doc-table{border-collapse:collapse;width:100%;font-size:13px}
.doc-table th{background:#eef2ff;color:var(--brand);font-size:12px;text-align:left;padding:9px 11px;border-color:#d3dcf3;width:32%}
.doc-table td{padding:9px 11px;border:1px solid var(--line);vertical-align:top;line-height:1.6}
.doc-table tbody tr:nth-child(even){background:#fafbfe}
.doc-ul,.doc-ol{margin:6px 0 14px;padding-left:22px}
.doc-ul li,.doc-ol li{margin:5px 0;line-height:1.65}
.doc-ul{list-style:disc}
.doc-ol{list-style:decimal}
.callout{border-radius:12px;padding:12px 16px;margin:14px 0 18px;border:1px solid transparent}
.callout .doc-h{margin-top:0}
.callout-warn{background:#fff4e5;border-color:#f0d3a4;color:#7a4b12}
.callout-goal{background:#eaf7f0;border-color:#bfe3cf;color:#1c6848}
.callout-firm{background:#fff0ea;border-color:#f2c9b5;color:#9c4a22}
.callout-secret{background:#fff8e1;border-color:var(--brand);color:#7a5a12;box-shadow:inset 4px 0 0 var(--brand)}
.callout-secret .doc-h.lvl1{border-bottom-color:var(--brand)}
.locked{display:grid;place-items:center;text-align:center;gap:10px;padding:26px 16px;background:#fafbfe;border:1px dashed var(--line);border-radius:14px;color:var(--muted)}
.locked strong{color:var(--ink);font-size:15px}
.mfoot{padding:12px 28px 14px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:11px;color:var(--muted);background:linear-gradient(180deg,var(--card) 0,#f4f6fb 100%);flex-shrink:0;position:relative}
.mfoot span:nth-child(1){font-weight:700;letter-spacing:.04em}
.mfoot::before{content:"";position:absolute;inset:0;border-radius:18px;background:radial-gradient(ellipse 200% 100% at 50% 100%,rgba(212,165,58,.04),transparent 60%)}
@media(max-width:1180px){
  .roundbar{grid-template-columns:repeat(2,minmax(0,1fr))}
  .grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:640px){
  .rr{padding:18px 12px 44px}
  .rr-top{gap:12px;margin-bottom:18px}
  .rr h1{font-size:24px;line-height:1.3}
  .rr-sub{font-size:12px;line-height:1.6}
  .rr-kicker{font-size:10px}
  .langbar button{padding:6px 11px;font-size:12px}
  .sectionhead{align-items:flex-start;margin-bottom:10px}
  .sectionhead h2{font-size:16px;line-height:1.4}
  .sectionhead span{font-size:11px}
  .progress{padding:11px 12px;margin-bottom:12px}
  .progress-meta{font-size:11px;gap:4px}
  .grid{grid-template-columns:1fr;gap:12px}
  .card-main{padding:16px}
  .card h3{font-size:20px;margin:10px 0 3px}
  .play{font-size:12px}
  .arrow{margin-top:12px;font-size:13px;padding:11px 12px}
  .rounddone{padding:12px;gap:10px;margin-top:14px;font-size:12px}
  .nextbtn{width:100%}
  .roundbar{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .roundtab{min-width:0;padding:11px 12px}
  .roundtab-top{font-size:12px;gap:6px;flex-wrap:wrap}
  .roundnum{width:22px;height:22px;font-size:11px;border-radius:7px}
  .pill{font-size:9px;padding:3px 6px;margin-left:auto}
  .roundtab small{font-size:10px;line-height:1.45;margin-top:6px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
  .notice{padding:14px;font-size:12px}
  .overlay{padding:8px;align-items:stretch}
  .modal{width:100%;max-height:94vh;max-height:calc(100dvh - 16px);border-radius:14px}
  .mhead{padding:13px 14px 11px;gap:8px;flex-direction:column}
  .mhead h2{font-size:18px;margin:6px 0 0}
  .mhead p{font-size:11px;line-height:1.5}
  .mhead-tools{gap:6px;width:100%;justify-content:space-between}
  .mhead-tools .langbar{padding:2px}
  .mhead-tools .langbar button{padding:5px 8px;font-size:11px}
  .xbtn{width:30px;height:30px;font-size:17px}
  .mbody{padding:14px 14px 24px;font-size:13px;line-height:1.7}
  .mfoot{padding:10px 14px;font-size:10px}
  .doc-h{font-size:14px;margin:16px 0 6px}
  .doc-h.lvl1{font-size:15px}
  .doc-h.lvl2{font-size:13px}
  .doc-table{min-width:420px;font-size:12px}
  .doc-table th{width:34%;font-size:11px;padding:7px 8px}
  .doc-table td{padding:7px 8px}
  .callout{padding:10px 12px;margin:12px 0 14px}
  .tablewrap,.doc-table-wrap{margin:8px 0 14px}
}
@media(max-width:380px){
  .roundbar{grid-template-columns:1fr}
  .mhead{flex-direction:column}
  .mhead-tools{width:100%;justify-content:space-between}
}
`;

function SectionBlock({ sec, lang }) {
  const paragraphs = L(sec.text, lang) || [];
  const bullets = L(sec.bullets, lang) || [];
  return (
    <div className={`sec${sec.tone === "firm" ? " firm" : ""}`}>
      <h4>{L(sec.title, lang)}</h4>
      {paragraphs.map((p, i) => <p key={i}>{p}</p>)}
      {bullets.length > 0 && <ul>{bullets.map((x, i) => <li key={i}>{x}</li>)}</ul>}
    </div>
  );
}

function SharedCase({ shared, lang }) {
  if (!shared) return null;
  return (
    <>
      <div className="sec">
        <h4>{lang === "th" ? "ส่วนที่ 1 · เรื่องราว (ทุกคนอ่านเหมือนกัน)" : "Part 1 · The case (everyone reads the same)"}</h4>
        {L(shared.intro, lang).map((p, i) => <p key={i}>{p}</p>)}
      </div>
      <div className="sec">
        <h4>{lang === "th" ? "เกิดอะไรขึ้น และเมื่อไร" : "What happened, and when"}</h4>
        <div className="tablewrap">
          <table>
            <thead><tr><th>{lang === "th" ? "เมื่อไร" : "WHEN"}</th><th>{lang === "th" ? "เกิดอะไรขึ้น" : "WHAT HAPPENED"}</th></tr></thead>
            <tbody>
              {L(shared.timeline, lang).map(([when, what], i) => <tr key={i}><td><strong>{when}</strong></td><td>{what}</td></tr>)}
            </tbody>
          </table>
        </div>
      </div>
      <div className="sec">
        <h4>{lang === "th" ? "ตัวเลขที่ทุกคนรู้" : "The numbers everyone can see"}</h4>
        <div className="tablewrap">
          <table>
            <thead><tr><th>{lang === "th" ? "เรื่อง" : "WHAT"}</th><th>{lang === "th" ? "ตัวเลข" : "THE NUMBER"}</th></tr></thead>
            <tbody>
              {L(shared.numbers, lang).map(([k, v], i) => <tr key={i}><td><strong>{k}</strong></td><td>{v}</td></tr>)}
            </tbody>
          </table>
        </div>
      </div>
      <div className="sec">
        <h4>{lang === "th" ? "การประชุม" : "The meeting"}</h4>
        {L(shared.meeting, lang).map((p, i) => <p key={i}>{p}</p>)}
      </div>
    </>
  );
}

function BlockItem({ blk }) {
  switch (blk.type) {
    case "heading":
      return <div className={`doc-h lvl${blk.level}`}>{blk.text}</div>;
    case "paragraph":
      return <p className="doc-p">{blk.text}</p>;
    case "note":
      return <p className="doc-note">{blk.text}</p>;
    case "table":
      return (
        <div className="doc-table-wrap">
          <table className="doc-table">
            <thead><tr><th>{blk.head[0]}</th><th>{blk.head[1]}</th></tr></thead>
            <tbody>
              {blk.rows.map((r, i) => <tr key={i}><td>{r[0]}</td><td>{r[1]}</td></tr>)}
            </tbody>
          </table>
        </div>
      );
    case "bullets":
      return <ul className="doc-ul">{blk.items.map((x, i) => <li key={i}>{x}</li>)}</ul>;
    case "steps":
      return <ol className="doc-ol" start={blk.start || 1}>{blk.items.map((x, i) => <li key={i}>{x}</li>)}</ol>;
    case "meta":
      return <p className="doc-meta">{blk.text}</p>;
    default:
      return null;
  }
}

function DocView({ blocks }) {
  const visible = blocks.filter((b) => b.type !== "meta");
  const out = [];
  let i = 0;
  while (i < visible.length) {
    const tone = visible[i].tone;
    if (tone) {
      const group = [];
      while (i < visible.length && visible[i].tone === tone) { group.push(visible[i]); i++; }
      out.push(
        <div className={`callout callout-${tone}`} key={`c${out.length}`}>
          {group.map((blk, j) => <BlockItem key={j} blk={blk} />)}
        </div>
      );
    } else {
      out.push(<BlockItem key={i} blk={visible[i]} />);
      i++;
    }
  }
  return <>{out}</>;
}

function Modal({ round, role, lang, onClose, onLang }) {
  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, [onClose]);

  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal" role="dialog" aria-modal="true" aria-label={L(role.name, lang)}>
        <div className="docstamp" aria-hidden="true">CLASSIFIED</div>
        <div className="mhead">
          <div className="mhead-tools">
            <div className="langbar" role="group" aria-label={lang === "th" ? "เลือกภาษา" : "Language"}>
              <button className={lang === "th" ? "on" : ""} onClick={() => onLang("th")}>ไทย</button>
              <button className={lang === "en" ? "on" : ""} onClick={() => onLang("en")}>EN</button>
            </div>
            <button className="xbtn" onClick={onClose} aria-label="Close">×</button>
          </div>
          <div className="mhead-title">
            <span className="chip">{L(role.code, lang)}</span>
            <h2>{L(role.name, lang)}</h2>
            <p>{L(role.play, lang)} · {L(round.title, lang)}</p>
          </div>
          <div className="docmeta">
            <span>Document No.: RR-{String(round.id).padStart(2, "0")}</span>
            <span>Effective Communication for Quality Team · MindDojo</span>
          </div>
        </div>
        <div className="mbody">
          {role.blocks ? (
            <DocView blocks={role.blocks[lang] || role.blocks.th} />
          ) : (
            <SharedCase shared={round.shared} lang={lang} />
          )}
        </div>
        <div className="mfoot">
          <span>Effective Communication for Quality Team · MindDojo</span>
          <span>{lang === "th" ? "เปลี่ยนภาษาได้ที่มุมซ้ายบน" : "Switch language at the top left"}</span>
        </div>
      </div>
    </div>
  );
}

export default function RoundRoleViewer() {
  const [lang, setLang] = useState("th");
  const [roundId, setRoundId] = useState(() => {
    try {
      const u = Math.max(1, Number(localStorage.getItem("rr-unlocked")) || 1);
      const r = Number(localStorage.getItem("rr-round")) || 1;
      return Math.min(Math.max(1, r), u, ROUNDS.length);
    } catch { return 1; }
  });
  const [selectedRole, setSelectedRole] = useState(null);
  const [activeRole, setActiveRole] = useState(null);
  const [confirmRole, setConfirmRole] = useState(null);
  const [unlocked, setUnlocked] = useState(ROUNDS.length);
  const [visited, setVisited] = useState(() => {
    try { return JSON.parse(localStorage.getItem("rr-visited")) || {}; } catch { return {}; }
  });

  const round = ROUNDS.find((r) => r.id === roundId);
  const readIds = visited[roundId] || [];
  const readCount = round.roles.filter((role) => readIds.includes(role.id)).length;
  const ready = round.available && readCount >= 1;
  const isLastRound = roundId === ROUNDS.length;

  useEffect(() => {
    try { localStorage.setItem("rr-unlocked", String(unlocked)); } catch {}
  }, [unlocked]);
  useEffect(() => {
    try { localStorage.setItem("rr-visited", JSON.stringify(visited)); } catch {}
  }, [visited]);
  useEffect(() => {
    try { localStorage.setItem("rr-round", String(roundId)); } catch {}
  }, [roundId]);

  const pickRound = (id) => {
    if (id > unlocked) return;
    setRoundId(id);
    setSelectedRole(null);
  };

  const openRole = (role) => {
    setVisited((prev) => {
      const seen = new Set(prev[roundId] || []);
      seen.add(role.id);
      return { ...prev, [roundId]: [...seen] };
    });
    setActiveRole(role);
  };

  const selectedRoleObj = round.roles.find((r) => r.id === selectedRole) || null;

  const finishRound = () => {
    if (!ready) return;
    if (!isLastRound) {
      const next = Math.min(roundId + 1, ROUNDS.length);
      setUnlocked((u) => Math.max(u, next));
      setRoundId(next);
      setSelectedRole(null);
    }
  };

  return (
    <div className="rr">
      <style>{CSS}</style>
      <div className="rr-wrap">
        <div className="docbar">
          <div className="docbar-left">
            <h1>{lang === "th" ? "เอกสาร (Documents)" : "Documents"}</h1>
            <p className="rr-sub">{lang === "th" ? "ไฟล์บทนำสู่การสื่อสาร · 4 ไฟล์รอบ" : "Role briefs · 4 files"}</p>
          </div>
          <div className="docbar-right">
            <div className="langbar" role="group" aria-label="Language">
              <button className={lang === "th" ? "on" : ""} onClick={() => setLang("th")}>ไทย</button>
              <button className={lang === "en" ? "on" : ""} onClick={() => setLang("en")}>EN</button>
            </div>
          </div>
        </div>

        <div className="round-step">
          <h2 className="round-step-title">{lang === "th" ? "เลือกรอบ (Round)" : "Select Round"}</h2>
          <div className="roundbar">
            {ROUNDS.map((r) => {
              const locked = r.id > unlocked;
              const done = r.id < unlocked;
              return (
                <button
                  key={r.id}
                  className={`roundtab${roundId === r.id ? " on" : ""}${locked ? " locked" : ""}`}
                  onClick={() => pickRound(r.id)}
                  disabled={locked}
                  aria-disabled={locked}
                >
                  <div className="roundtab-top">
                    <span className="roundnum">{locked ? "🔒" : r.id}</span>
                    <span>{lang === "th" ? `รอบที่ ${r.id}` : `Round ${r.id}`}</span>
                    <span className={`pill${locked ? " lock" : done ? " done" : ""}`}>
                      {locked
                        ? (lang === "th" ? "ถูกล็อก" : "LOCKED")
                        : done
                          ? (lang === "th" ? "เสร็จแล้ว" : "DONE")
                          : (r.available ? (lang === "th" ? "พร้อม" : "READY") : (lang === "th" ? "รอเอกสาร" : "NO BRIEF"))}
                    </span>
                  </div>
                  <small>{L(r.subtitle, lang)}</small>
                </button>
              );
            })}
          </div>
        </div>

        <main className="docmain">
          <div className="sectionhead">
            <h2>{L(round.title, lang)}</h2>
            <span>{lang === "th" ? "เปิดบทแล้วอ่านต่อได้เลยในหน้าเดียว" : "Open a role and read everything on one page"}</span>
          </div>

        <div className="progress">
          <div className="progress-meta">
            <span>
              {lang === "th"
                ? `รอบนี้ · เลือกบทแล้ว ${readCount} บท (ใช้ 1 บทก็พอ)`
                : `This round · ${readCount} role(s) selected (1 is enough)`}
            </span>
            <span className={ready ? "ok" : ""}>
              {ready
                ? (lang === "th" ? "✓ พร้อมไปรอบถัดไป" : "✓ Ready for the next round")
                : (lang === "th" ? "เลือกบทแล้วกดเปิดเอกสาร" : "Select 1 role, then press Open document")}
            </span>
          </div>
          <div className="track"><div className="fill" style={{ width: ready ? "100%" : "0%" }} /></div>
        </div>

        <div className="grid">
          {round.roles.map((role) => {
            const selected = selectedRole === role.id;
            const read = readIds.includes(role.id);
            return (
              <div key={role.id} className={`card${selected ? " sel" : ""}`} style={{ "--accent": `var(--${role.tone})`, "--soft": `var(--soft-${role.tone})` }}>
                <div className="strip" />
                <button className="card-main" onClick={() => { if (!round.available) return; setSelectedRole(role.id); }}>
                  <div className="cardhead">
                    <span className="rolebadge" aria-hidden="true">{role.id}</span>
                    <span className="chip">{L(role.code, lang)}</span>
                    {read && <span className="readmark">✓ {lang === "th" ? "อ่านแล้ว" : "Read"}</span>}
                  </div>
                  <h3>{L(role.name, lang)}</h3>
                  <p className="play">{L(role.play, lang)}</p>
                  <div className={`arrow${selected ? " on" : ""}`}>
                    {selected
                      ? (lang === "th" ? "✓ เลือกแล้ว · กดเปิดเอกสาร" : "✓ Selected · Press Open document")
                      : (lang === "th" ? "เลือกบทนี้ →" : "Select this role →")}
                  </div>
                </button>
              </div>
            );
          })}
        </div>

        <div className="openrow">
          <button
            className="openbtn"
            disabled={!round.available || !selectedRoleObj}
            onClick={() => { if (selectedRoleObj) setConfirmRole(selectedRoleObj); }}
          >
            {lang === "th" ? "เปิดเอกสาร →" : "Open document →"}
          </button>
        </div>

        {round.available && !isLastRound && (
          <div className={`rounddone${ready ? " ready" : ""}`}>
            <span>
              {ready
                ? (lang === "th" ? "เลือกบทแล้วพร้อมไปรอบถัดไป" : "Your role is selected. Continue when you are ready.")
                : (lang === "th" ? "กดเลือกบทนี้ 1 บทก็พอ" : "Just select the 1 role you will play.")}
            </span>
            <button className="nextbtn" disabled={!ready} onClick={finishRound}>
              {lang === "th" ? "เสร็จรอบนี้ · ไปรอบถัดไป →" : "Finish this round · Next →"}
            </button>
          </div>
        )}

        {round.available && isLastRound && ready && (
          <div className="notice ok">
            {lang === "th"
              ? "ครบทั้ง 4 รอบแล้ว 🎉 คุณสามารถกดย้อนไปดูรอบที่ผ่านได้เลย"
              : "All 4 rounds complete 🎉 You can go back to any round any time."}
          </div>
        )}

        {!round.available && (
          <div className="notice">
            {lang === "th"
              ? `ยังไม่ได้รับเอกสารของ Round ${round.id} จึงแสดงเฉพาะโครงสร้าง 3 บท (A/B/C) ไว้ก่อน เมื่อได้เอกสาร ให้เพิ่มข้อมูลใน ROUNDS ด้วยโครงสร้างเดียวกับ Round 1–4 ได้เลย`
              : `No brief was supplied for Round ${round.id}, so only the three role slots (A/B/C) are shown. When the documents arrive, add it to ROUNDS using the same shape as Rounds 1–4.`}
          </div>
        )}
        </main>

        {confirmRole && (
          <div className="cf-overlay" onMouseDown={(e) => e.target === e.currentTarget && setConfirmRole(null)}>
            <div className="cf-dialog" role="dialog" aria-modal="true" aria-label={lang === "th" ? "ยืนยันการเปิดเอกสารลับ" : "Confirm opening confidential document"}>
              <div className="cf-head">
                <span className="cf-stamp">{lang === "th" ? "เอกสารลับ" : "CONFIDENTIAL"}</span>
                <h2>{lang === "th" ? "ยืนยันก่อนเปิดเอกสาร" : "Confirm before opening"}</h2>
              </div>
              <p className="cf-text">
                {lang === "th"
                  ? `คุณกำลังจะเปิดเอกสารของ ${L(confirmRole.name, lang)} · ${L(confirmRole.play, lang)} เอกสารฉบับนี้เป็นความลับ ห้ามเปิดก่อนที่วิทยากรจะเฉลยเรื่องที่ซ่อนอยู่ และห้ามให้ผู้อื่นดู`
                  : `You are about to open the brief for ${L(confirmRole.name, lang)} · ${L(confirmRole.play, lang)}. This document is confidential. Do not open it before the facilitator reveals the secrets, and do not show it to anyone.`}
              </p>
              <div className="cf-actions">
                <button className="cf-cancel" onClick={() => setConfirmRole(null)}>
                  {lang === "th" ? "ยกเลิก" : "Cancel"}
                </button>
                <button className="cf-confirm" onClick={() => { openRole(confirmRole); setConfirmRole(null); }}>
                  {lang === "th" ? "ยืนยัน · เปิดเอกสาร" : "Confirm · Open document"}
                </button>
              </div>
            </div>
          </div>
        )}

        {activeRole && (
          <Modal
            key={`${round.id}-${activeRole.id}`}
            round={round}
            role={activeRole}
            lang={lang}
            onLang={setLang}
            onClose={() => setActiveRole(null)}
          />
        )}
      </div>
    </div>
  );
}
